    else if (idx == 3) return texture(shadowMaps[3], dir).r;
    else if (idx == 4) return texture(shadowMaps[4], dir).r;
    else if (idx == 5) return texture(shadowMaps[5], dir).r;
    else if (idx == 6) return texture(shadowMaps[6], dir).r;
